		function, err := s.catalog.metaDomain.FunctionDb(txCtx).GetByID(attachedFunction.FunctionID)
		if err != nil {
			log.Error("TryFinishAsyncAttachedFunctionInvocation: failed to get function", zap.Error(err))
			return err
		}
		if function == nil {
			log.Error("TryFinishAsyncAttachedFunctionInvocation: function not found",
				zap.String("function_id", attachedFunction.FunctionID.String()))
			return common.ErrFunctionNotFound
		}

		// Retrieve the collection record so we can compare its log position against the new offset.
