			// The collection's log has moved past the new offset: the attached function needs repair.
			response = &coordinatorpb.TryFinishAsyncAttachedFunctionInvocationResponse{
				Result: &coordinatorpb.TryFinishAsyncAttachedFunctionInvocationResponse_NeedsRepair{
					NeedsRepair: &coordinatorpb.AsyncAttachedFunctionNeedsRepair{
						CurrentCollectionLogOffset: uint64(collection.LogPosition),
					},
				},
			}
		} else {
			response = &coordinatorpb.TryFinishAsyncAttachedFunctionInvocationResponse{
				Result: &coordinatorpb.TryFinishAsyncAttachedFunctionInvocationResponse_Success{
					Success: &coordinatorpb.AsyncAttachedFunctionSuccess{
						UpdatedCompletionOffset: uint64(newOffset),
					},
				},
			}
		}
		return nil
	})

	if err != nil {
		return nil, err
	}

	return response, nil
}

